const input = $json.body ?? $json;
const text = (v) => v === null || v === undefined ? '' : String(v).trim();
const bool = (v) => typeof v === 'boolean' ? v : ['true','1','yes','on'].includes(text(v).toLowerCase());
const document_id = Number(input.document_id);
const chunk_size_chars = Number(input.chunk_size_chars ?? 1800);
const overlap_chars = Number(input.overlap_chars ?? 250);
const confirm_processing = bool(input.confirm_processing);
const errors = [];
if (!Number.isInteger(document_id) || document_id < 1) errors.push({field:'document_id',message:'شناسه سند معتبر نیست.'});
if (!Number.isInteger(chunk_size_chars) || chunk_size_chars < 500 || chunk_size_chars > 10000) errors.push({field:'chunk_size_chars',message:'اندازه Chunk معتبر نیست.'});
if (!Number.isInteger(overlap_chars) || overlap_chars < 0 || overlap_chars >= chunk_size_chars || overlap_chars > 2000) errors.push({field:'overlap_chars',message:'Overlap معتبر نیست.'});
if (confirm_processing !== true) errors.push({field:'confirm_processing',message:'پردازش باید تأیید شود.'});
return [{json:{document_id,chunk_size_chars,overlap_chars,confirm_processing,validation_status:errors.length?'invalid':'valid',errors}}];

if ($json.success !== true) return [{json:$json}];
const doc = $json.document_context;
const raw = String(doc.raw_text || '')
  .replace(/\r\n/g,'\n').replace(/\r/g,'\n')
  .replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();

const chunkSize = Number(doc.chunk_size_chars);
const overlap = Number(doc.overlap_chars);
const paragraphs = raw.split(/\n{2,}/).map(x=>x.trim()).filter(Boolean);
const pageOf = (t) => { const m=t.match(/\[\[PAGE:(\d+)\]\]/i); return m?Number(m[1]):null; };
const clean = (t) => t.replace(/\[\[PAGE:\d+\]\]/gi,'').trim();
const hash = (s) => {
  let h = 2166136261;
  for (let i=0;i<s.length;i++) { h ^= s.charCodeAt(i); h = Math.imul(h,16777619); }
  return (h>>>0).toString(16).padStart(8,'0');
};

let chunks=[],buffer='',section=null,page=null,index=0;

const emit = () => {
  const content=clean(buffer);
  if (!content) return;
  chunks.push({
    document_id:Number(doc.document_id),
    chunk_index:index++,
    page_start:page,
    page_end:page,
    section_title:section,
    content,
    content_hash:hash(content),
    token_estimate:Math.ceil(content.length/4),
    keywords:[]
  });
  buffer = overlap > 0 ? content.slice(-overlap) : '';
};

for (const p0 of paragraphs) {
  const p=clean(p0);
  const pg=pageOf(p0);
  if (pg!==null) page=pg;
  if (!p) continue;
  const heading=p.length<=120 && !/[.!?؟]$/.test(p) && p.split(/\s+/).length<=15;
  if (heading) section=p;
  if (!buffer) { buffer=p; continue; }
  if (buffer.length+2+p.length<=chunkSize) buffer += '\n\n'+p;
  else { emit(); buffer += (buffer?'\n\n':'')+p; }
}
emit();
if (!chunks.length) throw new Error('No chunks created.');

const total_chunks = chunks.length;

return chunks.map((chunk) => ({
  json: {
    ...chunk,
    total_chunks,
  },
}));

const rows = $input.all().map((item) => item.json);

if (!rows.length) {
  throw new Error('No chunk upsert results were returned.');
}

const document_id = Number(rows[0].document_id);
const total_chunks = Math.max(
  ...rows.map((row) => Number(row.total_chunks || 0))
);

const chunk_indexes = [
  ...new Set(
    rows.map((row) => Number(row.chunk_index))
  ),
];

if (
  !Number.isInteger(document_id) ||
  document_id < 1 ||
  !Number.isInteger(total_chunks) ||
  total_chunks < 1
) {
  throw new Error('Invalid chunk aggregation result.');
}

return [{
  json: {
    document_id,
    total_chunks,
    upserted_chunk_count: chunk_indexes.length,
    chunk_indexes,
  },
}];
